    public static int maxMeetings(int start[], int end[]) {
        PriorityQueue<List<Integer>> q=new PriorityQueue<>(
                (a,b)->Integer.compare(a.get(1),b.get(1)));
        for(int i=0;i<start.length;i++){
            q.add(Arrays.asList(start[i],end[i],i));
        }

        int res=0,nextSlot=0;
        while(!q.isEmpty()){
            List<Integer> list=q.poll();
            if(list.get(0)>nextSlot){
                nextSlot=list.get(1);
                res+=1;
            }
        }
        return res;

    }
